CREATE TABLE endpoints(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, saga_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('api-key','webhook')), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), key_hash TEXT, key_expires_at TEXT, signature_secret_hash TEXT, challenge TEXT NOT NULL DEFAULT 'none' CHECK(challenge IN ('none','echo-param')), rate_limit_per_minute INTEGER CHECK(rate_limit_per_minute IS NULL OR rate_limit_per_minute > 0), created_at TEXT NOT NULL, UNIQUE(org_id, name));
CREATE INDEX endpoints_org ON endpoints(org_id);
CREATE TABLE endpoint_events(endpoint_id TEXT NOT NULL REFERENCES endpoints(id), event_id TEXT NOT NULL, input_json TEXT NOT NULL CHECK(length(input_json) <= 4096), execution_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(endpoint_id, event_id));
CREATE TABLE endpoint_rate_windows(endpoint_id TEXT NOT NULL REFERENCES endpoints(id), window_start TEXT NOT NULL, hits INTEGER NOT NULL CHECK(hits >= 0), PRIMARY KEY(endpoint_id, window_start));
